const CATEGORIES_FEED = [
  { id: 'index', title: '지수', Comp: IndexCard },
  { id: 'close', title: '장마감 리뷰', Comp: CloseReviewCard },
  { id: 'portfolio', title: '포트폴리오', Comp: PortfolioCard },
  { id: 'alert', title: '알림', Comp: AlertCard },
  { id: 'news', title: '뉴스', Comp: NewsCard },
  { id: 'community', title: '커뮤니티', Comp: CommunityCard },
  { id: 'ranking', title: '랭킹', Comp: RankingCard },
  { id: 'watchlist', title: '관심 종목', Comp: WatchlistCard },
  { id: 'calendar', title: '증권 캘린더', Comp: CalendarCard },
  { id: 'report', title: '리포트', Comp: ReportCard },
];

function PreviewScreen({ onBack, onStart }) {
  const [order, setOrder] = useState(CATEGORIES_FEED.map((c) => c.id));
  const [dragId, setDragId] = useState(null);
  const [dragY, setDragY] = useState(0);
  const refs = useRef({});
  const pressTimer = useRef(null);
  const startY = useRef(0);

  useEffect(() => {
    const onMove = (e) => {
      const y = e.touches ? e.touches[0].clientY : e.clientY;
      if (pressTimer.current && Math.abs(y - startY.current) > 10) {
        clearTimeout(pressTimer.current);
        pressTimer.current = null;
      }
      if (!dragId) return;
      setDragY(y);
      let newIdx = 0;
      order.forEach((id) => {
        if (id === dragId) return;
        const r = refs.current[id]?.getBoundingClientRect();
        if (r && y > r.top + r.height / 2) newIdx++;
      });
      const curIdx = order.indexOf(dragId);
      if (newIdx !== curIdx) {
        const next = [...order];
        next.splice(curIdx, 1);
        next.splice(newIdx, 0, dragId);
        setOrder(next);
      }
    };
    const onUp = () => {
      if (pressTimer.current) { clearTimeout(pressTimer.current); pressTimer.current = null; }
      setDragId(null);
    };
    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
    return () => {
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup', onUp);
    };
  }, [dragId, order]);

  const onDown = (id, e) => {
    const y = e.touches ? e.touches[0].clientY : e.clientY;
    startY.current = y;
    pressTimer.current = setTimeout(() => { setDragId(id); setDragY(y); }, 450);
  };

  return (
    <Frame>
      <div style={{ position: 'absolute', top: 0, left: 0, right: 0, zIndex: 2, background: '#F3F4F5', padding: '16px 24px 4px' }}>
        <StatusBar />
        <div style={{ marginTop: 20 }}>
          <BackButton onClick={onBack} />
        </div>
      </div>
      <div style={{ flex: 1, overflowY: 'auto', padding: '100px 20px 148px', background: '#F3F4F5' }}>
        <div style={{ padding: '0 4px', fontFamily: FONT }}>
          <Illustration icon="reco" />
          <h1 style={{ fontSize: 22, fontWeight: 700, lineHeight: 1.35, margin: '4px 0 0', color: C.textPrimary, letterSpacing: '-0.3px' }}>홍길동님 맞춤 피드 미리보기</h1>
          <p style={{ fontSize: 14, color: C.textTertiary, margin: '8px 0 0' }}>드래그 해서 순서를 바꿀 수 있어요</p>
        </div>
        <div style={{ height: 20 }} />
        {order.map((id) => {
          const cat = CATEGORIES_FEED.find((c) => c.id === id);
          const dragging = dragId === id;
          const rect = refs.current[id]?.getBoundingClientRect();
          const style = {
            padding: '16px', marginBottom: 16, borderRadius: 16, fontFamily: FONT,
            background: C.white,
            boxShadow: dragging ? '0 8px 20px rgba(6,11,17,0.15)' : 'none',
            transform: dragging && rect ? `translateY(${dragY - (rect.top + rect.height / 2)}px) scale(1.02)` : 'none',
            position: dragging ? 'relative' : 'static',
            zIndex: dragging ? 5 : 1,
            touchAction: 'none',
          };
          const Comp = cat.Comp;
          return (
            <div key={id} ref={(el) => (refs.current[id] = el)} onPointerDown={(e) => onDown(id, e)} style={style}>
              <Comp />
            </div>
          );
        })}
      </div>
      <div style={{ position: 'absolute', left: 0, right: 0, bottom: 0, background: FOOTER_GRADIENT, padding: '20px 24px 28px', fontFamily: FONT, textAlign: 'center' }}>
        <button onClick={onStart} style={{ width: '100%', height: 56, borderRadius: 28, border: 'none', background: C.yellow, fontSize: 16, fontWeight: 700, color: C.textPrimary, cursor: 'pointer' }}>
          다음
        </button>
        <div style={{ fontSize: 12.5, color: C.textTertiary, marginTop: 12 }}>다음 화면에서 세부사항을 수정할 수 있어요</div>
      </div>
    </Frame>
  );
}

function RecommendScreen({ onManual, onPreview }) {
  const [activeTab, setActiveTab] = useState('reco');
  const [selectedCard, setSelectedCard] = useState('reco');
  const [pinned, setPinned] = useState(false);
  const refs = useRef({});
  const rowRef = useRef(null);
  const naturalTop = useRef(null);

  useEffect(() => { naturalTop.current = rowRef.current?.offsetTop; }, []);
  const onScroll = (e) => {
    if (naturalTop.current == null) return;
    setPinned(e.target.scrollTop >= naturalTop.current - 100);
  };

  const scrollTo = (key) => {
    setActiveTab(key);
    refs.current[key]?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  };

  const [expanded, setExpanded] = useState(false);
  const recoCard = {
    id: 'reco', label: '홍길동님 맞춤 피드', totalCount: 10,
    chips: ['시황 분석', '포트폴리오', '관심 종목', '지수', '알림', '증권 캘린더'],
    more: ['뉴스', '커뮤니티', '랭킹', '리포트'],
  };
  const recoSelected = selectedCard === 'reco';

  return (
    <Frame>
      <div style={{ position: 'absolute', top: 0, left: 0, right: 0, zIndex: 2, background: C.white, padding: '16px 24px 4px' }}>
        <StatusBar />
        <div style={{ width: 24, height: 24, display: 'flex', alignItems: 'center', color: C.textPrimary, marginTop: 20 }}>
          <BackIcon />
        </div>
      </div>

      <div onScroll={onScroll} style={{ flex: 1, overflowY: 'auto', paddingTop: 100, paddingBottom: 148 }}>
        <div style={{ padding: '20px 24px 0', fontFamily: FONT }}>
          <h1 style={{ fontSize: 24, fontWeight: 700, lineHeight: 1.35, margin: 0, color: C.textPrimary, letterSpacing: '-0.3px' }}>
            나만을 위한<br />투자 피드 만들기
          </h1>
          <p style={{ fontSize: 14, color: C.textTertiary, margin: '8px 0 0' }}>나에게 필요한 정보만 모아 볼 수 있어요.</p>
        </div>
        {pinned && <div style={{ height: 68 }} />}
        <div style={{ position: pinned ? 'absolute' : 'static', top: pinned ? 100 : 'auto', left: 0, right: 0, zIndex: 1 }}>
          <div ref={rowRef} className="no-scrollbar" style={{ display: 'flex', gap: 8, overflowX: 'auto', padding: '20px 24px 0', scrollbarWidth: 'none', msOverflowStyle: 'none', background: C.white }}>
          {FILTER_TABS.map((t) => (
            <button
              key={t.key}
              onClick={() => scrollTo(t.key)}
              style={{
                flexShrink: 0, height: 36, borderRadius: 8, padding: '0 12px', border: 'none', cursor: 'pointer',
                background: activeTab === t.key ? C.dark : C.chipBg,
                color: activeTab === t.key ? C.white : C.textSecondary,
                fontSize: 14, fontWeight: 600, fontFamily: FONT,
                display: 'flex', alignItems: 'center', gap: 4, whiteSpace: 'nowrap',
              }}
            >
              {t.key === 'reco' && <img src={ICONS.vector} alt="" style={{ width: 16, height: 16, display: 'block' }} />}
              {t.label}
            </button>
          ))}
          </div>
          <div style={{ height: 12, background: 'linear-gradient(180deg, #FFFFFF, rgba(255,255,255,0))', pointerEvents: 'none' }} />
        </div>

        <div ref={(el) => (refs.current.reco = el)} style={{ padding: '12px 17px 0' }}>
          <div
            onClick={() => setSelectedCard('reco')}
            style={{ position: 'relative', width: '100%', minHeight: 385, border: `2px solid ${recoSelected ? C.dark : C.borderLight}`, borderRadius: 19, padding: '32px 16px 18px', boxSizing: 'border-box', textAlign: 'center', fontFamily: FONT, overflow: 'hidden', cursor: 'pointer' }}
          >
            <div style={{
              position: 'absolute', top: 15, right: 15, width: 24, height: 24, borderRadius: 12,
              background: recoSelected ? C.yellow : 'transparent',
              border: recoSelected ? 'none' : `1.5px solid ${C.border}`,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
            }}>
              {recoSelected && <Check size={14} color={C.textPrimary} strokeWidth={3} />}
            </div>
            <div style={{ fontSize: 13, color: C.textTertiary }}>최근 90일 활동 이력 분석</div>
            <div style={{ fontSize: 19, fontWeight: 700, color: C.textPrimary, marginTop: 6 }}>{recoCard.label}</div>
            <div style={{ marginTop: 15, display: 'flex', justifyContent: 'center' }}>
              <CountBadge>{recoCard.totalCount}개 항목</CountBadge>
            </div>
            <div style={{ marginTop: 16, display: 'flex', justifyContent: 'center' }}>
              <Illustration icon="reco" />
            </div>
            <div style={{ marginTop: 16, display: 'flex', flexDirection: 'column', gap: 6 }}>
              <div style={{ display: 'flex', justifyContent: 'center', gap: 6 }}>
                {recoCard.chips.slice(0, 3).map((c) => <Chip key={c}>{c}</Chip>)}
              </div>
              <div style={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'center', gap: 6 }}>
                {recoCard.chips.slice(3).map((c) => <Chip key={c}>{c}</Chip>)}
                {expanded && recoCard.more.map((c) => <Chip key={c}>{c}</Chip>)}
                <span
                  onClick={(e) => { e.stopPropagation(); setExpanded(!expanded); }}
                  style={{ height: 24, borderRadius: 6, background: '#E5F4FF', padding: '0 8px', display: 'inline-flex', alignItems: 'center', fontSize: 12.5, fontWeight: 500, color: '#0090FF', whiteSpace: 'nowrap', fontFamily: FONT, cursor: 'pointer' }}
              >{expanded ? '- 접기' : `+${recoCard.more.length}개 더보기`}</span>
              </div>
            </div>
            <button
              onClick={(e) => { e.stopPropagation(); onPreview(recoCard); }}
              style={{ marginTop: 16, width: '100%', height: 43, borderRadius: 21.5, border: `1px solid ${C.border}`, background: 'transparent', fontSize: 14.5, fontWeight: 600, color: C.textPrimary, cursor: 'pointer', fontFamily: FONT }}
            >
              미리보기
            </button>
          </div>
        </div>

        {SECTIONS.map((section) => (
          <div key={section.key} ref={(el) => (refs.current[section.key] = el)} style={{ marginTop: 36 }}>
            <div style={{ fontSize: 18, fontWeight: 700, color: C.textPrimary, padding: '0 17px', fontFamily: FONT }}>{section.title}</div>
            <div className="no-scrollbar" style={{ display: 'flex', gap: 12, overflowX: 'auto', padding: '16px 17px 4px', scrollbarWidth: 'none', msOverflowStyle: 'none' }}>
              {section.cards.map((card) => (
                <PersonaCard key={card.id} card={card} selected={selectedCard === card.id} onSelect={setSelectedCard} onPreview={onPreview} />
              ))}
            </div>
          </div>
        ))}
      </div>

      <div style={{ position: 'absolute', left: 0, right: 0, bottom: 0, background: FOOTER_GRADIENT, padding: '48px 24px 28px', fontFamily: FONT }}>
        <button style={{ width: '100%', height: 56, borderRadius: 28, border: 'none', background: C.yellow, fontSize: 16, fontWeight: 700, color: C.textPrimary, cursor: 'pointer' }}>
          이 템플릿으로 시작하기
        </button>
        <div onClick={onManual} style={{ textAlign: 'center', marginTop: 14, fontSize: 14, fontWeight: 600, color: C.textTertiary, cursor: 'pointer' }}>직접 고르기</div>
      </div>
    </Frame>
  );
}

function ManualScreen({ onBack }) {
  const initial = {};
  ALL_CATEGORIES_FOR_MANUAL.forEach((cat) => cat.items.forEach((it) => (initial[`${cat.key}:${it}`] = false)));
  const [state, setState] = useState(initial);

  const toggle = (k) => setState((prev) => ({ ...prev, [k]: !prev[k] }));
  const count = Object.values(state).filter(Boolean).length;

  return (
    <Frame>
      <div style={{ position: 'absolute', top: 0, left: 0, right: 0, zIndex: 2, background: HEADER_GRADIENT, paddingBottom: 20 }}>
        <StatusBar />
        <div style={{ padding: '20px 24px 0', fontFamily: FONT }}>
          <BackButton onClick={onBack} bg={C.white} />
          <h1 style={{ fontSize: 24, fontWeight: 700, lineHeight: 1.35, margin: '16px 0 0', color: C.textPrimary, letterSpacing: '-0.3px' }}>
            보고 싶은 정보를<br />선택해주세요
          </h1>
        </div>
      </div>

      <div style={{ flex: 1, overflowY: 'auto', padding: `${HEADER_H - 8}px 24px 148px` }}>
        {ALL_CATEGORIES_FOR_MANUAL.map((cat) => (
          <div key={cat.key} style={{ marginTop: 24 }}>
            <div style={{ fontSize: 16, fontWeight: 700, color: C.textPrimary, marginBottom: 12, fontFamily: FONT }}>{cat.label}</div>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
              {cat.items.map((it) => {
                const k = `${cat.key}:${it}`;
                return <ToggleChip key={k} label={it} on={state[k]} onClick={() => toggle(k)} />;
              })}
            </div>
          </div>
        ))}
      </div>

      <div style={{ position: 'absolute', left: 0, right: 0, bottom: 0, background: FOOTER_GRADIENT, padding: '48px 24px 28px', fontFamily: FONT }}>
        <button style={{ width: '100%', height: 56, borderRadius: 28, border: 'none', background: C.yellow, fontSize: 16, fontWeight: 700, color: C.textPrimary, cursor: 'pointer' }}>
          {count}개 항목 · 피드 미리보기
        </button>
      </div>
    </Frame>
  );
}

export default function App() {
  const [screen, setScreen] = useState('main');
  const [previewCard, setPreviewCard] = useState(null);

  const openPreview = (card) => { setPreviewCard(card); setScreen('preview'); };

  return (
    <div style={{ padding: '1rem 0', display: 'flex', justifyContent: 'center', background: '#FAFAFA' }}>
      {screen === 'main' && <RecommendScreen onManual={() => setScreen('manual')} onPreview={openPreview} />}
      {screen === 'manual' && <ManualScreen onBack={() => setScreen('main')} />}
      {screen === 'preview' && (
        <PreviewScreen onBack={() => setScreen('main')} onStart={() => setScreen('main')} />
      )}
    </div>
  );
}
